	return {
		heroicStrike = { enabled = true },
		cleave = { enabled = true },
		rend = { enabled = true },
		thunderClap = { enabled = true },
		overpower = { enabled = true },
		execute = { enabled = true },
		sunderArmor = { enabled = true },
		revenge = { enabled = true },
		slam = { enabled = true },
		whirlwind = { enabled = true },
		shieldSlam = { enabled = true },
		devastate = { enabled = true },
		mortalStrike = { enabled = true },
		bloodthirst = { enabled = true },
		rampage = { enabled = true },
		deathWish = { enabled = true },
		sweepingStrikes = { enabled = true },
		hamstring = { enabled = true },
		shieldBash = { enabled = true },
		intercept = { enabled = true },
		intervene = { enabled = false },
		pummel = { enabled = true },
		battleShout = { enabled = true },
		commandingShout = { enabled = true },
		demoralizingShout = { enabled = true },
		intimidatingShout = { enabled = false },
		disarm = { enabled = false },
		concussionBlow = { enabled = true },
		piercingHowl = { enabled = false },
